import type { ImageRef } from '../types'

/**
 * Editorial illustration library. Files live in /public/images and are
 * generated by scripts/gen-images.mjs (duotone SVG compositions on the site
 * palette). No religious imagery: architecture, city, charts, business scenes
 * and speaker portraits only. A CMS will replace these with photography.
 *
 * Every image carries its alt text in Uzbek (the source) plus ru/en versions;
 * the content layer picks the one that matches the language of the text
 * around the image (src/content/index.ts).
 */
export const CREDIT = { uz: 'Illyustratsiya: Muomalat', ru: 'Иллюстрация: Muomalat', en: 'Illustration: Muomalat' } as const

type Alt = { uz: string; ru: string; en: string }

function make(src: string, alt: Alt, width: number, height: number): ImageRef {
  return {
    src: `/images/${src}.svg`,
    alt: alt.uz,
    width,
    height,
    credit: CREDIT.uz,
    translations: {
      ru: { alt: alt.ru, credit: CREDIT.ru },
      en: { alt: alt.en, credit: CREDIT.en },
    },
  }
}

const wide = (src: string, alt: Alt): ImageRef => make(src, alt, 1200, 800)
const square = (src: string, alt: Alt): ImageRef => make(src, alt, 800, 800)

