export type ImageKey = keyof typeof images

/**
 * Use a library image with an article-specific caption or alt text. An `alt`
 * override without `translations` is taken to be language-neutral (a person's
 * name on a portrait) and is used in every edition.
 */
export function img(key: ImageKey, overrides: Partial<ImageRef> = {}): ImageRef {
  const base = images[key]
  const { alt } = overrides
  const translations =
    overrides.translations ??
    (alt
      ? {
          ru: { alt, credit: base.translations?.ru?.credit },
          en: { alt, credit: base.translations?.en?.credit },
        }
      : base.translations)
  return { ...base, ...overrides, translations }
}
